shellCommands.command:
cat > /tmp/observe.mjs <<'EOF'
const res = await fetch('http://localhost:3111/product', {
  headers: { 'Accept-Encoding': 'identity' },
})
const reader = res.body.getReader()
const decoder = new TextDecoder()
let i = 0
const start = Date.now()
while (true) {
  const { done, value } = await reader.read()
  if (done) break
  const text = decoder.decode(value)
  console.log(`chunk ${i++} (+${Date.now() - start}ms) has_title=${text.includes('Premium Widget')} has_fallback=${text.includes('Checking availability')} has_stock=${/in stock/.test(text)}`)
}
EOF
node /tmp/observe.mjs

node -e "
const b=require('fs').readFileSync('.next/server/app/product.segments/product/__PAGE__.segment.rsc','utf8');
for (const m of ['Premium Widget','Checking availability','in stock']) console.log(m+': '+b.includes(m));
"
